// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 v1, uint256 v2) public {
        vm.assume(actor != address(c) && actor != address(0));
        v1 = bound(v1, 1, 10 ether);
        v2 = bound(v2, 1, 10 ether);
        uint256 total = v1 + v2;
        vm.deal(actor, total);

        // first deposit through the payable entry Put
        vm.prank(actor);
        c.Put{value: v1}(0);

        // second deposit through the fallback (plain ether transfer)
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: v2}("");
        assertTrue(ok);

        // GENERAL RULE: recorded balance is cumulative over all deposits
        // (both entry points) and equals the total value sent.
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == total);
    }
}
